Recursividad.ejemplo:
def factorial(n):
    if n <= 1:      # caso base
        return 1
    return n * factorial(n - 1)

Recursividad.solucion:
def suma(n):
    if n == 1:          # caso base
        return 1
    return n + suma(n - 1)

print(suma(4))   # 4 + 3 + 2 + 1 = 10

Recursividad.ejemplo3:
def potencia(base, exp):
    if exp == 0:          # caso base
        return 1
    return base * potencia(base, exp - 1)

print(potencia(2, 3))   # 2 * 2 * 2 = 8

